package com.aac.ieojwo.report.domain;
import com.aac.ieojwo.common.domain.BaseTimeEntity;import com.aac.ieojwo.device.domain.AacDevice;import com.aac.ieojwo.user.domain.AacUser;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="sensor_events",indexes=@Index(name="idx_sensor_user_time",columnList="aac_user_id,recorded_at"))public class SensorEvent extends BaseTimeEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="aac_user_id",nullable=false)private AacUser user;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="device_id")private AacDevice device;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private SensorEventType eventType;private Double numericValue;@Column(length=100)private String label;@Column(nullable=false)private Instant recordedAt;protected SensorEvent(){}public static SensorEvent create(AacDevice d,SensorEventType t,Double v,String l,Instant at){SensorEvent e=new SensorEvent();e.user=d.getUser();e.device=d;e.eventType=t;e.numericValue=v;e.label=l;e.recordedAt=at==null?Instant.now():at;return e;}public Long getId(){return id;}public SensorEventType getEventType(){return eventType;}public Double getNumericValue(){return numericValue;}public String getLabel(){return label;}public Instant getRecordedAt(){return recordedAt;}public AacUser getUser(){return user;}}
